export class Money {
  #cents;
  #currency;
  constructor(cents, currency) {
    this.#cents = cents;
    this.#currency = currency;
    Object.freeze(this);
  }
  get cents() { return this.#cents; }
  plus(other) { return new Money(this.#cents + other.#cents, this.#currency); }
}

